const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const native=globalThis.Native, storageKey='yubai-ledger-v1';
let state,loadError=false;
try {const raw=native?native.load():localStorage.getItem(storageKey);state=raw?C.restore(JSON.stringify({format:'yubai-backup',version:1,state:JSON.parse(raw)})):C.initialState();}
catch(e){state=C.initialState();loadError=true;}
let today=C.dayAt(new Date(),state.settings.timezone),month=today.slice(0,7),page='home',ledgerTab='all',query='',toastTimer,editTx=null;
let collector={native:false,authorized:false,connected:false},importPreview=[],restorePreview=null;
const icons={home:'M3 10L12 3L21 10M5 9V21H10V15H14V21H19V9',book:'M5 3H19V21H5ZM8 7H16M8 11H16M8 15H12',activity:'M4 5H20V21H4ZM8 2V8M16 2V8M4 10H20M8 14H10M14 14H16',chart:'M4 21V14H8V21M10 21V8H14V21M16 21V3H20V21',settings:'M12 8A4 4 0 1 0 12 16A4 4 0 1 0 12 8M12 2V5M12 19V22M2 12H5M19 12H22M5 5L7 7M17 17L19 19M5 19L7 17M17 7L19 5',plus:'M12 4V20M4 12H20',arrow:'M4 12H20M14 6L20 12L14 18',food:'M5 3V9Q5 12 9 12V21M9 3V12M13 3V9Q13 12 9 12M19 3V21M19 3Q14 9 19 12',transport:'M5 4H19V18H5ZM5 12H19M8 18V21M16 18V21M8 7H16M8 15H9M15 15H16',fun:'M4 6L20 4V19L4 21ZM4 10L20 8M9 13L15 15L9 18Z',goods:'M4 8H20L18 21H6ZM8 8V6A4 4 0 0 1 16 6V8',trip:'M3 9H21V20H3ZM8 9V5H16V9M8 9V20M16 9V20',fixed:'M6 3H18V21H6ZM9 7H15M9 11H15M9 15H12',other:'M12 3V21M3 12H21',income:'M12 3V18M6 12L12 18L18 12M4 21H20',refund:'M5 8H15A6 6 0 0 1 15 20H10M5 8L10 3M5 8L10 13',transfer:'M3 7H20M15 2L20 7L15 12M21 17H4M9 12L4 17L9 22',scan:'M3 8V3H8M16 3H21V8M21 16V21H16M8 21H3V16M3 12H21'};
function icon(n){return `<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${icons[n]||icons.other}" stroke-linecap="round" stroke-linejoin="round"/></svg></span>`;}
const amount=n=>`¥ ${C.yuan(n)}`;
function forecastDetails(s){
 const row=(label,value,key)=>`<div class="forecast-row"><span>${label}</span><strong data-forecast="${key}">${amount(value)}</strong></div>`;
 return `<h2>月底，还能留下多少</h2>`+
 row('按计划测算的月底资金',s.plannedForecast,'plan')+row('按近期消费节奏预测',s.rhythmForecast,'rhythm')+
 `<p class="muted" style="margin-top:16px">${s.basis==='recent'?'依据最近 7 个自然日的日常付款（含待补用途与零消费日）；旅行和固定费用另计剩余预留。':'数据不足或非当前月，暂按计划估算。至少记录满 7 天、3 笔日常付款后启用节奏预测。'}<br>两种预测均已计入待补用途的自动付款。补用途后由正式流水替换占款，修改或撤销后同步重算。未到账生活费不计入。</p>`+
 row('账户合计 · 按已记录账单推算',s.walletBalance,'accounts')+row('待补用途占款 · 预测中扣除',s.forecastPendingTotal,'pending')+
 row('预测使用资金 · 扣除占款后',s.forecastBalance,'balance')+row('尚需支出 · 按剩余计划',s.plannedFuture,'future')+
 `<p class="muted">待补用途占款不是已确认收支，包含尚未处理的往期自动付款。当前月日常预扣已从剩余计划中抵扣，不重复计算；非日常用途暂存仍保留资金占用，补充账户或用途后校正。付款账户未明确时暂按占款估算。</p>`;
}
const compact=n=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100);
const monthName=()=>`${Number(month.slice(0,4))} 年 ${Number(month.slice(5))} 月`;
const nowISO=()=>new Date().toISOString();
const sourceName=(s,record)=>record?.captureMethod==='accessibility-window-ai'?'窗口 OCR → DeepSeek':record?.captureMethod==='deepseek-fallback'?'DeepSeek 辅助':record?.captureMethod==='accessibility-window-ocr'?'窗口 OCR（无障碍）':({manual:'手动',notification:'通知',accessibility:'可读页面',ocr:'截图 OCR',screen_ocr:'屏幕 OCR（历史）',csv:'文件导入'}[s]||s);
function readStored(){const raw=native?native.load():localStorage.getItem(storageKey);return raw?C.restore(JSON.stringify({format:'yubai-backup',version:1,state:JSON.parse(raw)})):C.initialState();}
function reloadStored(){state=readStored();loadError=false;}
function persist(next){if(loadError)throw new Error('账本读取失败，请先恢复有效备份，避免覆盖原数据');if(native)throw new Error('原生账本须通过版本校验保存');localStorage.setItem(storageKey,JSON.stringify(next));state=next;}
function commit(type,value,options,queueIds=[]){
 if(loadError)throw new Error('账本读取失败，请先恢复有效备份，避免覆盖原数据');
 for(let attempt=0;attempt<3;attempt++){
  if(native)reloadStored();
  const expected=state.revision||0,next=C.reduce(state,{type,value,options});
  if(native){const result=native.commit(expected,JSON.stringify(next),JSON.stringify(queueIds));if(result==='conflict')continue;if(result!=='ok')throw new Error(result);state=next;}
  else persist(next);
  render();return;
 }
 reloadStored();render();throw new Error('账本刚刚更新，请检查当前记录后重试；本次操作未覆盖新流水');
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function guarded(fn){try{fn();}catch(e){const err=$('#form-error');if(err)err.textContent=e.message;else toast(e.message);}}
const actions={};
function action(name,fn){actions[name]=fn;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();guarded(()=>actions[el.dataset.action]?.(el));}});
const navItems=[['home','首页','home'],['ledger','账本','book'],['activities','生活安排','activity'],['stats','统计','chart'],['settings','设置','settings']];
function nav(){
  // Navigation owns persistent optical surfaces; a search or ledger update must not replace them.
  if(!$('#desktop-links')){
    const links=navItems.map(([id,label,ico])=>`<button class="nav-item" data-action="nav" data-page="${id}">${icon(ico)}<span>${label}</span></button>`).join('');
    $('#sidebar').innerHTML=`<div class="brand"><span class="brand-symbol">Y.</span><div><strong>余白</strong><span class="micro">A LITTLE ROOM FOR LIFE</span></div></div><div id="desktop-links">${links}</div><div class="side-foot"><div class="live"><i class="dot"></i>本地账本 · 离线可用</div>好好生活，留一点余白。<br><span class="micro">YUBAI / PERSONAL LEDGER</span></div>`;
    $('#mobile-nav').innerHTML=links;
  }
  for(const link of $$('#desktop-links [data-page],#mobile-nav [data-page]')){
    const active=link.dataset.page===page;
    if(link.classList.contains('active')!==active)link.classList.toggle('active',active);
    if(active&&link.getAttribute('aria-current')!=='page')link.setAttribute('aria-current','page');
    else if(!active&&link.hasAttribute('aria-current'))link.removeAttribute('aria-current');
  }
}
function head(label,subtitle,button=''){return `<div class="page-heading" data-folio="${String(navItems.findIndex(x=>x[0]===page)+1).padStart(2,'0')}"><div><h1>${label}</h1><div class="muted">${subtitle}</div></div>${button}</div>`;}
function button(label,act,primary=false,extra=''){return `<button type="button" class="btn ${primary?'primary':''}" data-action="${act}" ${extra}>${label}</button>`;}
function empty(title,copy,act='',label=''){return `<div class="empty"><div class="empty-mark">—</div><h3>${title}</h3><p>${copy}</p>${act?button(label,act):''}</div>`;}
function budgetRow(b){const allocated=b.allocated+b.shifts,percent=allocated>0?Math.min(100,Math.max(0,(b.spent-b.refund)/allocated*100)):b.spent?100:0;return `<div class="budget-row"><div class="category-icon">${icon(b.id)}</div><div><div class="budget-title">${esc(b.name)} ${b.remaining<0?'<span class="tag warn">超支</span>':''}</div><div class="bar"><i style="width:${percent}%"></i></div></div><div class="budget-value ${b.remaining<0?'negative':''}">${amount(b.remaining)}<small>剩余 / ${amount(allocated)}</small></div></div>`;}
function entry(t){const income=['income','refund'].includes(t.type),cat=t.splits?.[0]?.category||t.type;return `<button class="entry entry-edit ${t.status==='void'?'inactive':''}" data-action="detail" data-id="${esc(t.id)}"><div class="category-icon">${icon(cat)}</div><div class="entry-main"><div class="entry-title">${esc(t.merchant||C.TYPES[t.type])} ${t.status==='void'?'<span class="tag">已撤销</span>':''}</div><div class="entry-meta">${esc(C.dayAt(t.occurredAt,state.settings.timezone))} · ${esc(sourceName(t.source,t))} · ${esc(C.TYPES[t.type])}${t.type==='refund'&&C.monthOf(state,state.transactions.find(x=>x.id===t.refundOf))!==C.monthOf(state,t)?' · 往期退款':''}</div></div><span class="entry-value ${income?'positive':''}">${t.type==='transfer'?'↔':income?'+':'−'}${compact(t.amount)}</span></button>`;}
function transactions(){return state.transactions.filter(t=>C.monthOf(state,t)===month).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt));}
function pendingEntry(c){
 const recorded=c.autoRecorded&&c.status==='pending',hasPurpose=recorded&&typeof c.merchant==='string'&&!!c.merchant.trim(),title=recorded?(hasPurpose?c.merchant:'已记录付款 · 待补用途'):c.fundsStatus==='paid_out'?'转账 · 付款方已支付':c.merchant||(c.type==='complex'?'用途待核对':C.TYPES[c.type])||'交易信息待核对';
 const hold=recorded?(c.suspectedId||c.suspectedCandidateId?'疑似重复，未重复预扣；若确为另一笔消费，补充用途后计入。':c.holdReleased?'未预扣日常额度；仍可补充实际用途。':C.dayAt(c.occurredAt,state.settings.timezone)===today?'已先预扣今日可用额度；补用途后不会重复扣款。':'往日未补用途付款计入本月预占，今日额度按剩余天数调整。'):'';
 return `<article class="pending-box"><div class="section-head"><div class="entry-main"><h3 class="textwrap">${esc(title)}</h3>${hasPurpose?`<div class="entry-meta">${c.merchantEdited?'用途已填写 · 待核对类型':'商户已填入用途 · 待确认分类'}</div>`:''}</div><strong class="entry-value">${c.amount?amount(c.amount):'金额待核实'}</strong></div><div class="muted">${esc(sourceName(c.source,c))} · ${esc(C.dayAt(c.occurredAt,state.settings.timezone))}<br>${esc(c.reason)}${hold?'<br>'+esc(hold):''}</div><div class="actions">${recorded?button(hasPurpose?(c.merchantEdited?'查看用途':'确认分类'):'补用途','payment-purpose',true,`data-id="${esc(c.id)}"`):c.fundsStatus==='paid_out'&&c.status==='pending'?button('用途是消费','transfer-expense',true,`data-id="${esc(c.id)}"`):''}${recorded&&!c.holdReleased&&!c.suspectedId&&!c.suspectedCandidateId?button('非日常消费','release-payment-hold',false,`data-id="${esc(c.id)}"`):''}${!recorded&&c.status==='pending'?button(c.fundsStatus==='paid_out'?'核对其他用途':'核对入账','confirm',c.fundsStatus!=='paid_out',`data-id="${esc(c.id)}"`):c.status==='rejected'?'<span class="tag warn">失败 / 取消，不入账</span>':''}${c.suspectedId&&c.status==='pending'?button('关联为同一笔','merge',false,`data-id="${esc(c.id)}" data-tx="${esc(c.suspectedId)}"`):''}${button(c.suspectedId||c.suspectedCandidateId?'忽略重复记录':'忽略此候选','dismiss',false,`data-id="${esc(c.id)}"`)}</div></article>`;
}
function home(){
  const p=state.plans[month],s=C.summary(state,month,today),pending=s.pending.length,goal=p?.goalTarget??p?.savings??0;
  const available=s.availableToday??s.left,num=available===null?'—':compact(available),parts=num.split('.');
  const awaiting=!!p&&p.income>0&&(s.receivedPlan||0)<p.income&&month===today.slice(0,7),owed=awaiting?p.income-(s.receivedPlan||0):0;
  return head('给生活，留一点余白。',`${monthName()} · ${p?'每一笔，都为喜欢的生活留出空间。':'从一份月计划开始，慢慢养成自己的节奏。'}`,button(`${icon('plus')}记一笔`,'new',true))+
    (loadError?'<div class="notice">本地账本读取失败。已停止写入，请到设置恢复备份；原文件没有被覆盖。</div>':'')+
    (awaiting?`<div class="arrival" data-arrival><div><strong>生活费 ${amount(owed)} 还没到账</strong><span class="muted">到账前，月底资金先不做测算。</span></div><button class="btn" data-action="plan">标记到账</button></div>`:'')+
    `<section class="hero"><div class="hero-main"><div class="eyebrow"><i class="dot"></i>${p?(s.pendingPaymentTotal?'今日可用 · 含待补用途预扣':'今日参考剩余'):'本月生活，从容开始'}</div><div class="big-money ${available<0?'negative':''}"><small>¥</small>${parts[0]}${parts[1]?`<span class="decimal">.${parts[1]}</span>`:''}</div><div class="muted">${!p?'还没有月计划，先给每一份生活留好预算。':s.N?`${available<0?'今天已超出参考额度':'按当前日常预算计算'} · 本月还剩 ${s.N} 天`:'所选月份不计算今日额度'}</div><div class="hero-foot"><div><strong>${p?amount(s.availableTotal??s.total??0):'—'}</strong><span class="muted">今日参考总额</span></div><div><strong>${p?amount(s.T):'—'}</strong><span class="muted">今日已花 · 净额</span></div></div>${s.pendingPaymentTotal?`<p class="muted" style="margin-top:12px">待补用途 ${amount(s.pendingPaymentTotal)} · 其中今日预扣 ${amount(s.dailyHold)}</p>`:''}</div><div class="hero-side"><div><div class="eyebrow">${p?'日常预算剩余':'YOUR MONTH, YOUR PACE'}</div>${p?`<div class="serif">${amount(s.D)}</div><div class="muted">餐饮 · 交通 · 娱乐 · 日用品</div>`:'<p class="hero-copy">认真对待每一笔，<br>也好好享受每一天。</p>'}</div><div class="small-rule">${p?`<div class="eyebrow">月底资金 · 按计划测算</div>${awaiting&&s.plannedForecast<0?`<div data-forecast="home-plan" class="serif awaiting-figure" aria-label="暂不测算">— —</div><div class="muted">生活费到账后再测算</div>`:`<div data-forecast="home-plan" class="serif ${s.plannedForecast<0?'negative':''}">${amount(s.plannedForecast)}</div><div class="muted">${s.forecastPendingTotal?`已含待补用途占款 ${amount(s.forecastPendingTotal)}；`:"按已记录资金；"}未到账收入不计入</div>`}`:button('制定本月计划 ↗','plan',true)}</div></div></section>`+
    (s.pendingPaymentTotal?`<div class="notice" data-payment-hold><strong>待补用途 ${amount(s.pendingPaymentTotal)}</strong><br>${s.heldPayments} 笔付款已自动记下，按日常消费预扣，补充后校正。其中今日付款 ${amount(s.dailyHold)}；确认同一笔日常消费不会重复扣减。<button class="text-btn" data-action="pending">去补用途 ↗</button></div>`:'')+
    `<div class="strip"><div><span class="tag ${pending?'warn':''}">${pending?`${pending} 笔待确认`:'账本状态'}</span> <span class="muted">${pending?'核对后才会计入收支与预算。':p?'计划不等于到账；余额按已记录账单推算。':'基本记账不需要通知或图片权限。'}</span></div><button class="text-btn" data-action="${pending?'pending':'plan'}">${pending?'去核对':'查看月计划'} ↗</button></div>`+
    (p&&C.unassigned(state,month)<0?`<div class="notice">计划资金缺口 ${amount(-C.unassigned(state,month))}。可减少娱乐、延期活动或调整储蓄；必要生活底线不会自动降低。</div>`:'')+
    (state.closures[month]?.needsReview?'<div class="notice">月结后流水有变动，请在统计中重新核对月结。</div>':'')+
    `<div class="dashboard-grid"><div><section class="panel"><div class="section-head"><h2>让每份预算，各得其所</h2><button class="text-btn" data-action="${p?'adjust':'plan'}">${p?'调整预算':'开始分配'} ↗</button></div>${p?s.budgets.map(budgetRow).join(''):empty('预算还在等你的安排','餐饮、交通、娱乐，也为想去的地方留一份。','plan','创建月计划')}</section><section class="panel"><div class="section-head"><h2>最近的日常</h2><button class="text-btn" data-action="nav" data-page="ledger">全部账单 ↗</button></div>${transactions().slice(0,4).map(entry).join('')||empty('每一笔生活，都值得被记录','从今天的一顿饭、一杯咖啡开始。','new','记下第一笔')}</section></div><div><section class="savings-card"><div class="section-head"><h2>给未来的自己</h2><button class="text-btn" data-action="goal">储蓄目标 ↗</button></div><div class="amount">${amount(goal)}</div><div class="caption"><span>本月实际净结余</span><span>${amount(s.net)}</span></div><div class="bar"><i style="width:${goal?Math.min(100,Math.max(0,s.net/goal*100)):0}%"></i></div><p class="muted" style="margin-top:16px">预算预留 ${amount(s.savingsReserved)}<br>转入储蓄账户净额 ${amount(s.savingsTransferred)}<br>${p?.goalDeadline?'目标截止 '+esc(p.goalDeadline):'目标、预留、转存与净结余分别记录。'}</p><button class="text-btn" data-action="transfer">转入储蓄账户 ↗</button></section><section class="panel" style="margin-top:28px"><div class="section-head"><h2>值得期待的事</h2><button class="text-btn" data-action="nav" data-page="activities">生活安排 ↗</button></div>${state.activities.filter(a=>a.month===month&&a.status!=='cancelled').slice(0,2).map(a=>`<div class="entry"><div class="activity-date">${Number(a.date.slice(8))}</div><div class="entry-main"><div>${esc(a.name)}</div><div class="entry-meta">${esc(a.destination||a.date)} · 预留剩余 ${amount(C.budget(state,month,a.budgetId).remaining)}</div></div></div>`).join('')||'<p class="intro-copy">一场电影，一次短途旅行。<br>提前留出预算，让期待安心发生。</p>'}</section><div class="quote">“生活不必精打细算到每一秒，<br>但可以留一些从容给明天。”<small>A LITTLE ROOM FOR WHAT MATTERS.</small></div></div></div>`;
}
function ledger(){
 const list=transactions().filter(t=>!query||[t.merchant,C.TYPES[t.type],...(t.splits||[]).map(x=>C.categories(state)[x.category])].join(' ').includes(query));
 const pend=state.candidates.filter(c=>c.status==='pending'||c.status==='rejected');
 return head('把日常，记清楚。','每笔流水都有来源，每份预算有迹可循。',button(`${icon('plus')}记一笔`,'new',true))+
 `<div class="toolbar"><div class="search"><input id="search" aria-label="搜索账单" placeholder="搜索商户、分类或交易类型" value="${esc(query)}"></div>${button('识别微信付款','payment-recognition')}${button('截图补记与适配','screenshot-learn')}${button('普通截图识别','ocr')}${button('导入账单','import')}</div><div class="tabs"><button class="${ledgerTab==='all'?'active':''}" data-action="tab" data-tab="all">本月流水 ${transactions().length}</button><button class="${ledgerTab==='pending'?'active':''}" data-action="tab" data-tab="pending">待核对 ${pend.length}</button></div>`+
 (ledgerTab==='pending'?`<p class="muted">未补用途与失败记录不混入正式收支。今日已记录付款的预扣单独显示，补用途后才更新消费分类与预算。这里显示所有月份的未处理记录。</p>${pend.map(pendingEntry).join('')||empty('没有待处理的记录','不确定的识别结果会先放在这里。')}`:list.map(entry).join('')||empty('还没有找到记录',query?'试试其他商户或分类关键词。':'手动、截图和文件导入都汇入同一本账。','new','记一笔'));
}
function activities(){const p=state.plans[month],s=C.summary(state,month,today),food=s.budgets.find(b=>b.id==='food');const weekStart=new Date(today+'T12:00:00Z');weekStart.setUTCDate(weekStart.getUTCDate()-((weekStart.getUTCDay()+6)%7));const week=C.dayAt(weekStart,'UTC');
 const foodWeek=transactions().filter(t=>t.status==='confirmed'&&t.type==='expense'&&C.dayAt(t.occurredAt,state.settings.timezone)>=week&&C.dayAt(t.occurredAt,state.settings.timezone)<=today).reduce((n,t)=>n+t.splits.filter(x=>x.budgetId==='food').reduce((a,x)=>a+x.amount,0),0);
 return head('让期待，有个位置。','先留好预算，再安心去生活。',button(`${icon('plus')}新安排`,'activity',true))+
 `<div class="summary-grid"><div class="stat"><label>本周日常餐饮已用</label><strong>${compact(foodWeek)}</strong></div><div class="stat"><label>餐饮周参考预算</label><strong>${food&&p?compact(Math.floor((food.allocated+food.shifts)/(C.daysInMonth(month)-p.startDay+1)*7)):'—'}</strong></div><div class="stat"><label>固定费用剩余预留</label><strong>${compact(s.budgets.find(b=>b.id==='fixed')?.remaining||0)}</strong></div></div>`+
 (p?`<div class="notice">固定费用扣款日：每月 ${p.fixedDay||1} 日；已记支付 ${amount(s.budgets.find(b=>b.id==='fixed')?.spent||0)}。请按真实扣款记账，计划不会自动生成消费。${p.arrivalDay?` 计划到账日：${p.arrivalDay} 日。`:''}</div>`:'')+
 state.activities.filter(a=>a.month===month).map(a=>{const b=C.budget(state,month,a.budgetId);return `<article class="activity"><div class="activity-top"><div><span class="micro">${esc(a.destination||'A PLAN TO LOOK FORWARD TO')}</span><h2>${esc(a.name)}</h2><span class="muted">${esc(a.date)}</span></div><span class="tag">${a.status==='cancelled'?'已取消':'已预留'}</span></div><div class="activity-details"><span>预算 ${amount(b.allocated+b.shifts)}</span><span>净已用 ${amount(b.spent-b.refund)}</span><span class="${b.remaining<0?'negative':''}">剩余 ${amount(b.remaining)}</span></div>${Object.entries(a.components||{}).map(([k,v])=>`<span class="tag">${esc(k)} ${amount(v)}</span> `).join('')}<div class="form-actions">${a.status!=='cancelled'?button('记录活动消费','activity-spend',true,`data-budget="${esc(a.budgetId)}"`)+button('取消 / 释放预留','cancel-activity',false,`data-id="${esc(a.id)}"`)+button('跨月保留','carry-activity',false,`data-id="${esc(a.id)}"`):'<span class="muted">仅释放未使用资金；已支付部分须实际退款后恢复。</span>'}</div></article>`;}).join('')+
 (!state.activities.some(a=>a.month===month)?empty('为下一次小确幸，提前留白','活动预留从已有预算划出，实际消费后只保留未使用部分。','activity','安排一件期待的事'):'');
}
function stats(){const s=C.summary(state,month,today),p=state.plans[month],closed=state.closures[month],daily=Array.from({length:C.daysInMonth(month)},(_,i)=>transactions().filter(t=>t.status==='confirmed'&&t.type==='expense'&&Number(C.dayAt(t.occurredAt,state.settings.timezone).slice(8))===i+1).reduce((n,t)=>n+t.amount,0)),max=Math.max(...daily,1);
 return head('看见生活的节奏。','统计、预算与首页，共用同一本地账本。')+
 `<div class="summary-grid"><div class="stat"><label>实际收入</label><strong>${compact(s.income)}</strong><p class="muted">计划 ${amount(p?.income||0)}</p></div><div class="stat"><label>已确认消费</label><strong>${compact(s.expenses)}</strong><p class="muted">退款另列 ${amount(s.refunds)}</p></div><div class="stat"><label>本月实际净结余</label><strong class="${s.net<0?'negative':''}">${compact(s.net)}</strong><p class="muted">收入 − 消费 ＋ 退款</p></div></div><div class="dashboard-grid"><div><section class="panel"><h2>这个月，花在哪里</h2><div class="histogram" role="img" aria-label="${monthName()} 每日支出柱状图，总支出 ${amount(s.expenses)}">${daily.map((n,i)=>`<div style="height:${n?n/max*100:1}%" title="${i+1}日：${amount(n)}"></div>`).join('')}</div><div class="hist-labels"><span>01</span><span>15</span><span>${C.daysInMonth(month)}</span></div>${s.budgets.map(budgetRow).join('')}</section><section class="panel"><div class="section-head"><h2>按消费分类</h2>${button("管理分类","categories")}</div>${s.categorySpending.length?s.categorySpending.map(c=>`<div class="forecast-row"><span>${esc(c.name)}</span><strong>${amount(c.net)}</strong></div>`).join(''):'<p class="muted">已确认的消费与退款在这里按分类汇总。</p>'}<p class="muted">消费减退款；待补用途付款核对分类后计入。不额外扣预算。</p></section></div><div><section class="panel">${forecastDetails(s)}<div class="forecast-row"><span>生活费已到账 / 计划</span><span>${amount(s.receivedPlan)} / ${amount(p?.income||0)}</span></div><div class="forecast-row"><span>往期消费退款 · 待分配</span><span>${amount(s.previousRefund)}</span></div><div class="forecast-row"><span>未分配计划资金</span><span>${amount(C.unassigned(state,month))}</span></div></section><section class="panel"><h2>月末，认真收个尾</h2><p class="muted" style="margin-top:12px">${closed?closed.needsReview?'月结后记录有变，请重新核对。':'本月已核对关闭。':'先核对到账、遗漏和退款，再关闭月份。'}<br>账户余额自然延续到下月，不新增收入。跨月活动需单独保留预留。</p>${button(closed?'重新打开本月':'核对并关闭月份',closed?'reopen':'close',false)}</section></div></div>`;
}
const THEMES=[['paper','序曲 · 印纸','细线、墨色与克制的显影。'],['lens','透镜 · 印纸','透光、局部反射与轻柔回弹。'],['daylight','日光 · 液态玻璃','暖白纸面，浮层是透亮的玻璃。'],['stage','夜灯 · 液态玻璃','深墨与暖光，浮层是会回弹的玻璃。']];
const appearanceOf=t=>t==='lens'?'lens':t==='stage'||t==='daylight'?'glass':'paper';
function themeChoices(){const selected=['lens','daylight','stage'].includes(state.settings.theme)?state.settings.theme:'paper';return `<div class="theme-grid" role="group" aria-label="外观主题">${THEMES.map(([id,name,copy])=>`<button type="button" class="theme-choice" data-action="apply-theme" data-theme="${id}" aria-pressed="${selected===id}"><span class="theme-preview ${id}" aria-hidden="true"><small>${({paper:'OVERTURE / 01',lens:'LENS / 02',daylight:'DAYLIGHT / 03',stage:'NIGHT / 04'})[id]}</small><b>55.00</b></span><strong>${name}</strong><p>${copy}</p><span class="selection-note">${selected===id?'● 正在使用':'选择这个主题 ↗'}</span></button>`).join('')}</div>`;}
function capturePromptPanel(){return `<section class="panel"><h2>截图完成提示</h2><div class="setting-row"><div><h3>${collector.capturePromptEnabled?'系统通知已允许':'尚未允许系统通知'}</h3><p class="muted">截到付款图后发送短时系统通知，可从通知栏查看“可离开页面”。提示不代表记账成功。是否弹出横幅由系统控制；关闭此提示不影响识别和自动记账。</p></div>${button(collector.capturePromptEnabled?'提示设置':'开启截图提示','capture-prompt-permission',false,native?.capturePromptPermission?'':'disabled')}</div></section>`;}
function pageCapturePanel(){
 const enabled=!!state.settings.pageCapture,selected=state.settings.sources.includes('com.tencent.mm');
 const status=!native?'仅 Android APK 可用':!enabled?'未启用':!selected?'请启用微信采集来源':!collector.accessibilityAuthorized?'等待系统授权':!collector.accessibilityConnected?'已授权，服务未连接':({pending:'付款已提取，后台正在处理；用途稍后补充',unreadable:'当前页面不可读取，请改用分享截图',ignored:'等待支持的微信交易详情页',error:'读取异常，请重新打开服务'}[collector.accessibilityState]||'已连接，等待微信交易详情页');
 return `<section class="panel"><h2>微信页面识别 · 实验功能</h2><div class="notice">${esc(status)}${collector.accessibilityError?'<br>'+esc(collector.accessibilityError):''}</div><p class="muted">通知未出现时，可尝试读取系统实际提供的微信付款结果或转账详情文字。启用成功付款自动记录后，明确付款会在后台保存并预扣日常可用额度；用途可稍后补充。受保护、不可读或未适配页面请分享截图或手动记账。</p><div class="setting-row"><div><h3>可读交易详情</h3><p class="muted">只保存交易必要字段，不保存整页或聊天正文。服务已连接不代表当前页面可读，请以读取状态为准。</p></div>${button(enabled?'系统授权设置':'了解并启用','page-permission',false,native?'':'disabled')}${enabled?button('停用','page-disable'):''}</div><div class="setting-row"><div><h3>微信付款窗口 OCR</h3><p class="muted">${state.settings.pageOcr?esc(collector.pageOcrMessage||'已启用，等待微信扫码付款、商家支付结果或转账详情窗口'):'默认关闭 · 文字不可读时，仅尝试已适配的微信支付结果及转账详情窗口。Android 14 及以上，本地处理，每次打开仅作一次高清识别。'}</p></div>${button(state.settings.pageOcr?'关闭增强':'启用窗口 OCR',state.settings.pageOcr?'page-ocr-disable':'page-ocr-permission',false,native&&collector.pageOcrSupported?'':'disabled')}</div></section>`;
}
function alipayCapturePanel(){
 const selected=state.settings.sources.includes('com.eg.android.AlipayGphone'),enabled=state.settings.alipayPageCapture===true;
 const status=!enabled?'未启用':!selected?'请启用支付宝采集来源':!state.settings.pageCapture||!state.settings.pageOcr?'页面识别或窗口 OCR 总开关已关闭':!collector.accessibilityConnected?'等待无障碍服务连接':'已启用 · 等待支持的支付宝付款页面';
 return `<section class="panel"><h2>支付宝付款识别 · 实验功能</h2><p class="notice">${esc(status)}</p><p class="muted">独立开启后，在已适配的支付宝付款成功页或消费账单详情中进行本地窗口 OCR。成功付款先记金额、预扣今日可用额度，用途稍后编辑。账单订单号可能需要展开「更多」；未读到标识时保留疑似重复提示。</p><p class="muted">支付宝与微信按来源分别查重。充值、还款、退款和收款不当作消费；未适配或受保护页面不会自动扣款。</p><div class="form-actions">${button(enabled?'查看读取范围':'了解并启用','alipay-page-permission',true,native&&collector.pageOcrSupported?'':'disabled')}${enabled?button('停用支付宝页面识别','alipay-page-disable'):''}</div></section>`;
}
function processingStatus(){return native?`<div class="status-line">后台记账：${esc(({processing:'正在处理付款',updated:'付款已保存',error:'处理异常，采集记录保留',idle:'等待新的付款'}[collector.processorState]||'等待新的付款'))}${collector.processorLast?' · 最近更新 '+esc(C.dayAt(collector.processorLast,state.settings.timezone)):''}${collector.processorError?'<br>'+esc(collector.processorError)+' '+button('重试处理','process-payments'):''}</div>`:'';}
function deepSeekPanel(){const a=JSON.parse(native?.deepSeekStatus?.()||'{}');return `<section class="panel"><div class="section-head"><h2>DeepSeek 识别兜底</h2><span class="tag">${a.enabled?'已启用 · 失败时联网':'默认关闭'}</span></div><p class="muted">本地识别成功时不调用。高清本地识别失败后立即请求 DeepSeek。看到“已截取付款图”提示后可离开页面，已截取的图片会继续在后台识别。已授权付款窗口中的明确付款会自动查重、记录并预扣今日额度，用途可后补和编辑；信息不明或疑似重复时不再扣款。普通截图识别仍离线；云端截图入口是「截图补记与适配」。</p><p class="notice">${esc(a.message||'尚未配置')}${a.lastMs?' · 上次 '+(a.lastMs/1000).toFixed(1)+' 秒':''}</p>${button('配置云端识别','deepseek-settings',false,native?.configureDeepSeek?'':'disabled')}</section>`;}
function settings(){return head('账本，由你掌握。','采集范围、资金账户与数据备份。')+
 `<section class="panel"><div class="section-head"><h2>资金账户</h2>${button('添加账户','account')}</div>${state.accounts.map(a=>`<div class="setting-row"><div><h3>${esc(a.name)} <span class="tag">${{wallet:'日常 / 储值',savings:'储蓄',credit:'信用'}[a.type]}</span></h3><p class="muted">按已记录账单推算 · 期初 ${amount(a.opening)} · ${a.openingDay&&a.openingDay!=='1970-01-01'?esc(a.openingDay):'未设置期初日期'}</p></div><div><strong>${amount(C.accountBalance(state,a.id))}</strong> <button class="text-btn" data-action="account" data-id="${esc(a.id)}">编辑</button></div></div>`).join('')}<p class="muted" style="margin-top:12px">储值卡充值、提现、自己的账户之间转存与还信用本金，请用「账户间转账」。实际购买记消费；手续费单独记一笔消费。</p></section>`+
 `<section class="panel"><h2>支付信息采集</h2><div class="notice">${native?collector.error?esc(collector.error):!collector.authorized?'未授权 · 基本功能照常可用':!collector.connected?'已授权，监听未连接 · 请重新打开通知使用权':'监听已连接 · 仅收集所选来源中的支付服务通知':'当前为浏览器预览，通知监听与本地 OCR 需安装 Android APK'}<br>成功付款在后台保存；未补用途的预扣与正式消费分开显示。上次采集：${collector.last?esc(C.dayAt(collector.last,state.settings.timezone)):'尚无记录'}。</div><div class="setting-row"><div><h3>系统通知使用权</h3><p class="muted">只保存必要交易字段；无关通知立即丢弃。</p></div>${button('前往设置','permission',false,native?'':'disabled')}</div>${[['com.tencent.mm','微信支付'],['com.eg.android.AlipayGphone','支付宝']].map(([id,name])=>`<div class="setting-row"><div><h3>${name}</h3><p class="muted">已实现保守解析 · 真实支付场景尚未验证</p></div><label class="switch"><input type="checkbox" data-setting-source="${id}" ${state.settings.sources.includes(id)?'checked':''} aria-label="采集${name}"></label></div>`).join('')}<div class="setting-row"><div><h3>成功付款自动记录</h3><p class="muted">读取后先记金额并预扣日常额度，用途稍后补。失败、金额不明和疑似重复先核对；关闭后新记录不自动预扣。</p></div><label class="switch"><input type="checkbox" id="auto-record-payments" ${state.settings.autoRecordPayments!==false?'checked':''} aria-label="成功付款自动记录"></label></div><p class="muted" style="margin-top:16px">已成功付出的微信转账先记金额，借款或还款可标为「非日常消费」释放预扣。红包和退款继续核对。NFC 触碰本身不能确定金额；首版未适配银行、校园卡或交通卡。没有系统付款通知时，可启用下方无障碍窗口 OCR；目前已实测微信付款方待收款详情。</p></section>`+
 processingStatus()+capturePromptPanel()+deepSeekPanel()+pageCapturePanel()+alipayCapturePanel()+customRulesPanel(state.settings.customRules||[])+
 `<section class="panel"><h2>备份与导出</h2><div class="setting-row"><div><h3>完整备份</h3><p class="muted">含账户、预算、目标、活动、流水、候选与关联。明文 JSON，请妥善保存。</p></div>${button('保存备份','backup')}</div><div class="setting-row"><div><h3>恢复账本</h3><p class="muted">先验证并预览，再替换当前账本；失败保留原数据。</p></div>${button('选择备份','restore')}</div><div class="setting-row"><div><h3>恢复前副本</h3><p class="muted">每次恢复时自动保留上一份本地账本。</p></div>${button('导出副本','recovery')}</div><div class="setting-row"><div><h3>CSV 流水导出</h3><p class="muted">供核对与表格查看；拆分与账户转账关系请用完整备份保留。</p></div>${button('导出 CSV','export')}</div><div class="setting-row"><div><h3>账单导入模板</h3><p class="muted">支持余白 v1 UTF-8 CSV。平台原始账单暂不直接支持。</p></div>${button('下载模板','template')}</div></section>`+
 `<section class="panel"><div class="section-head"><h2>消费分类</h2>${button("管理分类","categories")}</div><p class="muted">可以添加、重命名或停用自己的分类。分类说明花在哪里，承担预算决定扣哪一份钱。</p></section><section class="panel"><h2>账本偏好</h2><div class="setting-row"><div><h3>账本时区</h3><p class="muted">${esc(state.settings.timezone)} · 有流水后锁定，避免静默改变归属月。</p></div>${button('设置','timezone')}</div><div class="setting-row"><div><h3>给账本，换一种质感</h3><p class="muted">四种质感，同一本账。动效与透明度跟随系统偏好。</p></div></div>${themeChoices()}</section><p class="muted">余白 0.2.31 · 本地账本试用版<br>基本功能离线可用；可选 DeepSeek 兜底联网，不读取支付应用私有数据库。请结合实际账单定期核对。</p>`;}
function render(){
  Motion.beforeRender();
  native?.backEnabled?.($('#sheet').open||page!=='home');
  today=C.dayAt(new Date(),state.settings.timezone);document.documentElement.dataset.theme=state.settings.theme==='stage'?'stage':'paper';document.querySelector('meta[name=theme-color]')?.setAttribute('content',state.settings.theme==='stage'?'#0c0a09':'#eee8dc');nav();
  $('#main').innerHTML=`<header class="topbar"><div class="wordmark"><em>Y.</em><div><span>余白</span><small>ROOM FOR LIFE</small></div></div><div class="month-control"><label class="month-picker"><span>${Number(month.slice(0,4))} 年 ${Number(month.slice(5))} 月</span><span aria-hidden="true">⌄</span><input id="month" type="month" value="${month}" aria-label="选择账本月份"></label>${page!=='settings'?`<button class="icon-button" aria-label="选择外观主题" data-action="appearance">${icon('settings')}</button>`:''}</div></header>`+
    ({home,ledger,activities,stats,settings}[page]||home)()+`<footer class="footer-note"><span>好好生活，留一点余白。</span><span>LOCAL FIRST · CNY</span></footer>`;
  $('#month').onchange=e=>{if(/^\d{4}-\d{2}$/.test(e.target.value)){month=e.target.value;render();}};
  if(appearanceOf(state.settings.theme)==='glass')mountGlassMonth($('.month-picker'),{value:month,today,onPick:v=>{month=v;render();}});
  if($('#search'))$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};
  $$('[data-setting-source]').forEach(el=>el.onchange=()=>guarded(()=>{const selected=new Set(state.settings.sources);el.checked?selected.add(el.dataset.settingSource):selected.delete(el.dataset.settingSource);commit('SETTINGS',{sources:[...selected]});}));
  if($('#auto-record-payments'))$('#auto-record-payments').onchange=e=>guarded(()=>commit('SETTINGS',{autoRecordPayments:e.target.checked}));
  Motion.afterRender({page,month,appearance:appearanceOf(state.settings.theme)});
}
let transactionEditor=null,ruleEditor=null;
function sheet(title,body,onSubmit,{kind='default'}={}){
  ruleEditor?.destroy();ruleEditor=null;transactionEditor?.destroy();transactionEditor=null;$('#sheet').dataset.kind=kind;
  $('#sheet-content').innerHTML=`<div class="dialog-head"><h2 id="sheet-title">${title}</h2><button type="button" data-action="close-sheet" aria-label="关闭弹窗">×</button></div><form id="form">${body}<div id="form-error" role="alert"></div></form>`;
  $('#form').onsubmit=e=>{e.preventDefault();guarded(()=>onSubmit?.(Object.fromEntries(new FormData(e.target)),e.target));};
  if(kind==='transaction')transactionEditor=mountTransactionEditor($('#form'),{icon,createCategory:name=>{const id='cat-'+C.uid();commit('CATEGORY',{id,name});return state.categories.find(c=>c.id===id);}});
  Motion.openSheet();
  if(!$('#sheet').open)$('#sheet').showModal();
  native?.backEnabled?.(true);
}
window.closeSheet=()=>{if($('#sheet').open){Motion.closeSheet(()=>$('#sheet').close());return true;}return false;};
$('#sheet').addEventListener('cancel',e=>{e.preventDefault();if(!transactionEditor?.dismissPicker())window.closeSheet();});
$('#sheet').addEventListener('close',()=>{if($('#sheet').open)return;ruleEditor?.destroy();ruleEditor=null;transactionEditor?.destroy();transactionEditor=null;Motion.sheetClosed();native?.backEnabled?.(page!=='home');});
$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)window.closeSheet();}});
window.handleBack=()=>{if(transactionEditor?.dismissPicker())return true;if(window.closeSheet())return true;if(page!=='home'){page='home';render();return true;}return false;};
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const cashField=(label,name,value='',extra='')=>field(label,name,value,'text',`inputmode="decimal" ${extra}`);
const submit=(label='保存')=>`<div class="form-actions"><button class="btn" type="button" data-action="close-sheet">取消</button><button class="btn primary" type="submit">${label}</button></div>`;
const currentDate=()=>month===today.slice(0,7)?today:month+'-01';
const localClock=iso=>new Intl.DateTimeFormat('en-GB',{timeZone:state.settings.timezone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(iso));
function planReceiptFields(p=null){
 const received=p?C.summary(state,p.month,today).receivedPlan:0,complete=!!p&&p.income>0&&received>=p.income;
 const unmatched=state.transactions.filter(t=>t.type==='income'&&t.status==='confirmed'&&!t.incomePlan&&C.monthOf(state,t)===month);
 return `<div class="form-divider"><label class="checkbox-note"><input type="checkbox" name="allowanceReceived" ${complete?'checked disabled':''}><span>生活费已到账${complete?' · 已全额入账':''}</span></label><p class="muted">勾选表示计划生活费已全部到账。${p?`已匹配 ${amount(received)}，只补未到账差额。`:''}未勾选只保存计划，不增加余额。已计入期初余额的资金不要再次新增收入。</p>${complete?'<p class="muted">到账状态根据实际流水计算；需要更正请到账本修改或撤销收入。</p>':`<fieldset data-plan-receipt hidden disabled style="border:0;padding:0;margin-top:12px"><div class="form-grid">${field('实际到账日期','receiptDay',currentDate(),'date',`required min="${month}-01" max="${month}-${C.daysInMonth(month)}"`)}<div class="field"><span>新增收入存入账户</span>${state.accounts.map(a=>`<label class="checkbox-note"><input type="radio" name="receiptAccountId" value="${esc(a.id)}" ${a.id==='cash'?'checked':''} required><span>${esc(a.name)}</span></label>`).join('')}</div></div>${unmatched.length?`<div class="form-note" style="margin-top:12px">已手动记过的生活费，请选中关联，系统只补剩余差额：</div>${unmatched.map(t=>`<label class="checkbox-note"><input type="checkbox" name="receiptExisting" value="${esc(t.id)}"><span>${esc(C.dayAt(t.occurredAt,state.settings.timezone))} · ${esc(t.merchant||'实际收入')} · ${amount(t.amount)}</span></label>`).join('')}`:''}</fieldset>`}</div>`;
}
function bindPlanReceipt(){const toggle=$('[name=allowanceReceived]'),group=$('[data-plan-receipt]');if(toggle&&group)toggle.onchange=()=>{group.hidden=!toggle.checked;group.disabled=!toggle.checked;};}
function receiptFromForm(f,form){return f.allowanceReceived?{accountId:f.receiptAccountId,occurredAt:C.localInstant(f.receiptDay,state.settings.timezone),existingIncomeIds:new FormData(form).getAll('receiptExisting')}:null;}
function planSheet(){
 const old=state.plans[month];
 if(old){const sum=C.summary(state,month,today);sheet('本月计划',`<p class="muted">${monthName()} · ${old.startDay} 日启用。预算与实际到账分开；可在下方登记已到账生活费。</p><div class="forecast-row"><span>计划生活费</span><strong>${amount(old.income)}</strong></div><div class="forecast-row"><span>已匹配到账</span><strong>${amount(sum.receivedPlan)}</strong></div><div class="forecast-row"><span>分配合计</span><strong>${amount(C.allocationTotal(old))}</strong></div><div class="forecast-row"><span>未分配 / 缺口</span><strong>${amount(C.unassigned(state,month))}</strong></div>${sum.budgets.map(budgetRow).join('')}${planReceiptFields(old)}${sum.receivedPlan<old.income?submit('保存到账状态'):''}<div class="form-actions">${button('登记分批到账','income')}${button('预算调拨','adjust')}${button('修订收入计划','plan-income')}</div>`,(f,form)=>{const receipt=receiptFromForm(f,form);if(receipt)commit('RECEIVE_PLAN',{month,...receipt});window.closeSheet();toast(receipt?'生活费到账已匹配，不重复计入收入':'到账状态未更改');});bindPlanReceipt();return;}
 const rows=Object.entries(C.CATEGORIES).filter(([id])=>id!=='other');
 sheet('把这个月，安排好',`<p class="muted">填写本月计划。月中开始时，将预算填写为剩余安排，并在账户中登记当前期初资金。</p><div class="form-grid">${cashField('本月生活费 · 必填','income','','required')}${cashField('储蓄目标 · 必填','savings','','required')}${field('启用日','startDay',month===today.slice(0,7)?Number(today.slice(8)):1,'number',`min="1" max="${C.daysInMonth(month)}" required`)}${field('储蓄目标截止','goalDeadline',`${month}-${C.daysInMonth(month)}`,'date','required')}${field('计划到账日','arrivalDay',1,'number','min="1" max="31"')}${field('固定费用扣款日','fixedDay',1,'number','min="1" max="31"')}${cashField('餐饮必要底线（剩余期间）','foodFloor','0','required')}${cashField('交通必要底线（剩余期间）','transportFloor','0','required')}<div class="form-divider"><button class="btn" type="button" data-action="suggest-plan">按生活底线生成分配</button> ${native?'':'<button class="text-btn" type="button" data-action="sample-plan">填入 3000 元验收方案</button>'}</div>${rows.map(([id,label])=>cashField(label+'预算',id,'0','required')).join('')}${cashField('应急预留','emergency','0','required')}<div class="form-note" id="plan-total">先填写生活费和储蓄目标，再生成或手动分配。不可行计划可以保存，但会明确显示缺口。</div>${planReceiptFields()}</div>${submit('保存月计划')}`,(f,form)=>{
   const p={month,income:C.money(f.income),savings:C.money(f.savings),emergency:C.money(f.emergency),startDay:Number(f.startDay),goalDeadline:f.goalDeadline,arrivalDay:Number(f.arrivalDay),fixedDay:Number(f.fixedDay),budgets:rows.map(([id,name])=>({id,name,allocated:C.money(f[id]),daily:['food','transport','fun','goods'].includes(id),floor:C.money(id==='food'?f.foodFloor:id==='transport'?f.transportFloor:'0')}))};
   const receipt=receiptFromForm(f,form);commit('PLAN',p,receipt?{receipt}:undefined);window.closeSheet();toast(receipt?'月计划与生活费收入已保存；已有到账不会重复计入':'月计划已保存；账户余额未增加');
 });
 bindPlanReceipt();
 $('#form').addEventListener('input',()=>{try{const f=Object.fromEntries(new FormData($('#form'))),sum=rows.reduce((n,[id])=>n+C.money(f[id]||'0'),0)+C.money(f.savings||'0')+C.money(f.emergency||'0'),gap=C.money(f.income||'0')-sum;$('#plan-total').textContent=`已分配 ${amount(sum)} · ${gap<0?'缺口':'未分配'} ${amount(Math.abs(gap))}${gap<0?'；建议减少娱乐、延期出游或调整储蓄目标，必要生活底线不会自动降低。':''}`;}catch{}});
}
function txSheet({type='expense',tx=null,candidate=null,budgetId=null,distinctPayment=false}={}){
 editTx=tx;
 const date=tx?C.dayAt(tx.occurredAt,state.settings.timezone):candidate?C.dayAt(candidate.occurredAt,state.settings.timezone):currentDate();
 const txMonth=date.slice(0,7),p=state.plans[txMonth],selectedType=tx?.type||type;
 const editable=tx?.id,split=tx?.splits?.[0],recorded=!!candidate?.autoRecorded;
 const candidateNotice=recorded?`<div class="notice">这笔付款已自动记录。${candidate.merchant?`商户 / 用途已填写为「${esc(candidate.merchant)}」，可直接使用或修改。`:''}${distinctPayment?'你已选择这确实是另一笔付款，将独立计入消费。':candidate.holdReleased||candidate.suspectedId||candidate.suspectedCandidateId?'此记录目前没有预扣日常额度，补成消费后按实际用途计入。':'同额日常消费补用途后会替换对应预扣，不会再扣一次。'} 请核对实际日期、分类和预算；修改金额或预算会校正额度和月底预测；待补用途占款会由正式流水替换。借款或代付选择「待核对」，自己的账户转存选择「转账」。</div>`:candidate?`<div class="notice">${esc(candidate.reason)}<br>请按实际交易核对金额、类型与日期。失败付款、未实际到账的收入或未领取红包不能确认为已完成流水。付款方已支付但对方待收款的转账，请按本人实际支出与用途核对。</div>`:'';
 sheet(recorded?'补充这笔付款的用途':candidate?'核对这笔交易':editable?'修改账单':'记下这一笔',`${candidateNotice}<div class="form-grid">${select('交易类型','type',Object.entries(C.TYPES).filter(([k])=>!tx||k!=='complex'),selectedType)}${cashField('实际金额','amount',tx?C.yuan(tx.amount):candidate?.amount?C.yuan(candidate.amount):'','required')}${field('交易日期','date',date,'date','required')}${field('交易时间','clock',localClock(tx?.occurredAt||candidate?.occurredAt||nowISO()),'time','required')}${field('商户 / 用途','merchant',tx?.merchant||candidate?.merchant||'','text','maxlength="120"')}${select('付款 / 入账账户','accountId',state.accounts.map(a=>[a.id,a.name]),tx?.accountId||candidate?.accountId||'cash')}${select('转入账户（仅转账）','toAccountId',state.accounts.map(a=>[a.id,a.name]),tx?.toAccountId||'savings')}${select('消费分类','category',Object.entries(C.categories(state)).filter(([id])=>!state.categories?.find(c=>c.id===id)?.archived||id===(split?.category||candidate?.category)),split?.category||candidate?.category||'food')}${select('承担预算（只扣这一项）','budgetId',(p?.budgets||[]).map(b=>[b.id,b.name]),budgetId||split?.budgetId||candidate?.budgetId||candidate?.category||'food')}<label class="field full"><span>关联原消费（仅退款）</span><select name="refundOf"><option value="">请选择原消费</option>${state.transactions.filter(t=>t.type==='expense'&&t.status==='confirmed').map(t=>`<option value="${esc(t.id)}" ${tx?.refundOf===t.id?'selected':''}>${esc(C.dayAt(t.occurredAt,state.settings.timezone))} ${esc(t.merchant||'消费')} ${amount(t.amount)}</option>`).join('')}</select></label><label class="field full checkbox-note"><span><input type="checkbox" name="matchPlan" ${tx?.incomePlan?'checked':''}> 此收入匹配到账月生活费计划（分批核销）</span></label><div class="field full"><span>拆分消费（可选，每行：金额, 分类英文键, 预算项 ID）</span><textarea name="splits" placeholder="例如：15, food, food&#10;5, goods, goods">${tx?.splits?.length>1?esc(tx.splits.map(x=>`${C.yuan(x.amount)}, ${x.category}, ${x.budgetId}`).join('\n')):''}</textarea><div class="muted">分类：${Object.entries(C.categories(state)).map(([id,name])=>`${esc(name)}=${esc(id)}`).join(" / ")}。活动预算 ID 可在活动消费中自动选择；不拆分时留空。</div></div><div class="form-note">期初余额在设置中登记。充值、提现、还本金用账户间转账；手续费另记消费。借款、AA、代付、报销暂不建立正式流水。${p?'':'该日期尚无月计划，记消费前请先建立。'}</div></div>${candidate&&!recorded?'<label class="checkbox-note"><input name="verifyActual" type="checkbox" required><span>我已核对支付详情，确认资金实际成功变动，金额、方向和日期正确。</span></label>':''}${submit(recorded?'保存用途':candidate?'确认并入账':'保存账单')}`,(f)=>{
   const original=tx?.occurredAt||candidate?.occurredAt;const a=C.money(f.amount),occurredAt=original&&f.date===date&&f.clock===localClock(original)?original:C.localInstant(f.date,state.settings.timezone,f.clock);
   const splits=f.type!=='expense'?[]:f.splits.trim()?f.splits.trim().split('\n').map(line=>{const [a,category,budgetId]=line.split(',').map(x=>x.trim());return {amount:C.money(a),category,budgetId};}):[{amount:a,category:f.category,budgetId:f.budgetId}];
   const transaction={...(tx||{}),type:f.type,amount:a,merchant:f.merchant,accountId:f.accountId,toAccountId:f.type==='transfer'?f.toAccountId:null,occurredAt,splits:f.type==='expense'?splits:[],refundOf:f.type==='refund'?f.refundOf:null,incomePlan:f.type==='income'&&f.matchPlan?f.date.slice(0,7):null};
   if(f.type==='complex'){if(candidate)commit('UPDATE_PENDING',{id:candidate.id,amount:a,merchant:f.merchant,occurredAt});else commit('INGEST',{id:C.uid(),fingerprint:'manual:'+C.uid(),source:'manual',origin:'manual',reference:'',amount:a,type:'complex',merchant:f.merchant,occurredAt,collectedAt:nowISO(),status:'pending',successful:false,reliable:false,reason:'复杂用途暂存，尚未计入正式收支'});window.closeSheet();toast(recorded?'用途已保存，日常预扣已释放；仍未计入正式收支':'已保存为待确认，不计入正式收支');return;}
   if(tx)transaction.status='confirmed';
   if(candidate)commit('CONFIRM',{id:candidate.id,transaction,distinctPayment});else commit('POST',transaction);
   window.closeSheet();toast(state.closures[f.date.slice(0,7)]?'已保存，请重新核对历史月结':'账单已保存，预算与统计已同步');
 },{kind:'transaction'});
 $('#form [name="date"]').onchange=e=>{const p=state.plans[e.target.value.slice(0,7)],budget=$('#form [name="budgetId"]'),previous=budget.value;budget.innerHTML=(p?.budgets||[]).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('');if([...budget.options].some(o=>o.value===previous))budget.value=previous;};
 if(candidate&&!recorded){const verify=$('#form [name="verifyActual"]'),typeInput=$('#form [name="type"]');const update=()=>{verify.required=typeInput.value!=='complex';};typeInput.addEventListener('change',update);update();}
 const typeInput=$('#form [name="type"]');
 const showRelevantFields=()=>{const kind=typeInput.value;for(const [name,types] of Object.entries({toAccountId:['transfer'],category:['expense'],budgetId:['expense'],refundOf:['refund'],matchPlan:['income'],splits:['expense']})){const el=$(`#form [name="${name}"]`);el.closest('.field').hidden=!types.includes(kind);}$('#form [name="accountId"]').previousElementSibling.textContent=kind==='transfer'?'转出账户':['income','refund'].includes(kind)?'入账账户':'付款账户';};
 typeInput.addEventListener('change',showRelevantFields);showRelevantFields();
}
function details(id){const t=state.transactions.find(x=>x.id===id),sources=state.candidates.filter(c=>c.transactionId===id);sheet('账单详情',`<div class="big-money" style="font-size:52px">${amount(t.amount)}</div><dl class="detail-grid"><dt>类型 / 状态</dt><dd>${esc(C.TYPES[t.type])} · ${t.status==='void'?'已撤销':'已确认'}</dd><dt>商户 / 用途</dt><dd>${esc(t.merchant||'未填写')}</dd><dt>发生时间</dt><dd>${esc(t.occurredAt)}</dd><dt>采集时间</dt><dd>${esc(t.collectedAt)}</dd><dt>来源</dt><dd>${esc(sourceName(t.source,t))}</dd><dt>承担预算</dt><dd>${(t.splits||[]).map(x=>`${esc(C.categories(state)[x.category])} → ${esc(state.plans[C.monthOf(state,t)]?.budgets.find(b=>b.id===x.budgetId)?.name||x.budgetId)} ${amount(x.amount)}`).join('<br>')||'不扣消费预算'}</dd><dt>收入计划</dt><dd>${esc(t.incomePlan||'未匹配')}</dd><dt>原消费 ID</dt><dd>${esc(t.refundOf||'—')}</dd><dt>来源关联</dt><dd>${sources.map(c=>`${esc(sourceName(c.source,c))} · ${esc(c.reference||'无交易号')} · ${esc(c.status)}`).join('<br>')||'手工录入'}</dd></dl><div class="form-actions">${t.status==='confirmed'?button('修改','edit-tx',true,`data-id="${esc(id)}"`):''}${button(t.status==='void'?'恢复这笔账':'撤销这笔账','void-tx',false,`data-id="${esc(id)}"`)}</div>`);}
function adjust(){const p=state.plans[month];if(!p)return planSheet();const items=[...p.budgets.map(b=>[b.id,b.name]),['savings','储蓄预留'],['emergency','应急预留'],['unassigned','待分配资金']];sheet('让预算，跟上生活',`<p class="muted">仅改变计划预留，不改变真实余额、收入或消费。超支本身照实记录。</p><div class="form-grid">${select('从哪里调出','from',items,'fun')}${select('调入哪里','to',items,'food')}${cashField('调拨金额','amount','','required')}<label class="field full checkbox-note"><span><input name="confirmReserve" type="checkbox"> 我确认这次调拨涉及的储蓄 / 应急预留调整。</span></label></div>${submit('确认调拨')}`,f=>{commit('ADJUST',{month,from:f.from,to:f.to,amount:C.money(f.amount),confirmReserve:!!f.confirmReserve});window.closeSheet();toast('预算已调拨，账户余额不变');});}
function activitySheet(){const p=state.plans[month];if(!p)return planSheet();sheet('留一件期待的事',`<div class="form-grid">${field('活动名称','name','','text','required maxlength="60"')}${field('日期','date',currentDate(),'date','required')}${field('目的地 / 地点','destination','','text','maxlength="100"')}${select('从哪项预算预留','from',p.budgets.filter(b=>!b.carried).map(b=>[b.id,b.name]),'trip')}${['交通','住宿','餐饮','门票','机动费用','其他单项费用'].map((k,i)=>cashField(k,'part'+i,'0','required')).join('')}<div class="form-note">合计从现有预算划出，不额外占用一份资金。跨月活动请在目标月建立计划后使用「跨月保留」。</div></div>${submit('预留并保存')}`,f=>{const components=Object.fromEntries(['交通','住宿','餐饮','门票','机动费用','其他单项费用'].map((k,i)=>[k,C.money(f['part'+i])]));commit('ACTIVITY',{month,name:f.name,date:f.date,destination:f.destination,from:f.from,components,amount:Object.values(components).reduce((n,v)=>n+v,0)});window.closeSheet();toast('活动预留已保存');});}
function exportFile(text,name,mime){if(native){native.exportFile(text,name,mime);return;}const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function chooseFile(kind){if(native){({ocr:()=>native.pickImage(),csv:()=>native.pickCSV(),backup:()=>native.pickBackup()}[kind])();return;}if(kind==='ocr'){toast('本地中文 OCR 需安装 Android APK；浏览器可手工输入识别文字');sheet('核对支付文字',`<p class="muted">浏览器不执行图片 OCR。粘贴支付结果文字，只生成待确认候选。</p><label class="field"><span>支付结果文字</span><textarea name="text" required></textarea></label>${submit('解析为待确认')}`,f=>{commit('INGEST',C.parsePayment(f.text));window.closeSheet();page='ledger';ledgerTab='pending';render();});return;}
 const input=$('#file');input.value='';input.accept=kind==='csv'?'.csv,text/csv':'.json,application/json';input.onchange=async()=>{try{if(input.files[0]?.size>20e6)throw new Error('文件不能超过 20 MB');const text=await input.files[0].text();kind==='csv'?previewCSV(text):previewBackup(text);}catch(e){toast(e.message);}};input.click();}
function previewCSV(text){importPreview=C.importCSV(text,state);const errors=importPreview.filter(r=>r.error);sheet('导入预览',`<p>共 ${importPreview.length} 行 · 可解析 ${importPreview.length-errors.length} 行 · 失败 ${errors.length} 行</p><p class="muted">所有有效行先进入待核对；相同交易标识会关联，疑似重复需人工确认。不支持的列或格式不会静默导入。</p>${importPreview.slice(0,30).map(c=>c.error?`<div class="error">${esc(c.error)}</div>`:`<div class="entry"><div class="entry-main">${esc(c.merchant||C.TYPES[c.type])}<div class="entry-meta">${esc(c.occurredAt)} · ${c.status==='rejected'?'失败 / 取消':'待核对'}</div></div><span>${amount(c.amount)}</span></div>`).join('')}${importPreview.length>30?'<p class="muted">预览仅显示前 30 行。</p>':''}${submit('将有效行加入待核对')}`,()=>{commit('INGEST',importPreview.filter(x=>!x.error),{auto:false});window.closeSheet();page='ledger';ledgerTab='pending';render();toast('导入候选已保存，请逐笔核对');});}
function previewBackup(text){restorePreview=C.restore(text);if(restorePreview.settings.customRules)restorePreview.settings.customRules=rulesAfterRestore(restorePreview.settings.customRules);const expectedRaw=native?native.load():localStorage.getItem(storageKey);sheet('恢复前，核对一下',`<p>备份版本 ${restorePreview.version} · ${restorePreview.transactions.length} 笔流水 · ${Object.keys(restorePreview.plans).length} 个月计划 · ${restorePreview.activities.length} 项活动</p><div class="notice">恢复会替换当前账本。确认后先自动保留一份当前账本的恢复前副本；原始文件和格式验证失败不会覆盖账本。恢复的自定义规则先停用，需重新测试和绑定窗口。若预览期间又记录了付款，请重新预览后再恢复。</div><label class="checkbox-note"><input name="confirm" type="checkbox" required><span>我已核对备份内容，同意用此备份替换当前账本。</span></label>${submit('确认恢复')}`,()=>{
   const previous=state,wasError=loadError;loadError=false;
   try{if(native){let expected;try{expected=JSON.parse(expectedRaw||'{"revision":0}').revision;}catch{}const result=Number.isSafeInteger(expected)&&expected>=0?native.replaceCAS(expected,JSON.stringify(restorePreview)):native.replaceCorrupt(expectedRaw||'',JSON.stringify(restorePreview));if(result==='conflict')throw new Error('预览期间账本已更新，请关闭并重新选择备份，核对新增付款后再恢复');if(result!=='ok')throw new Error(result);reloadStored();}else{const raw=localStorage.getItem(storageKey);if(raw!==expectedRaw)throw new Error('预览期间账本已更新，请重新选择备份');if(raw)localStorage.setItem(storageKey+'-before-restore',raw);persist(restorePreview);}}catch(e){loadError=wasError;throw e;}
   window.closeSheet();render();toast('账本已恢复，请核对账户与预算');
 });}
function drain(process=true){if(!native)return;try{const known=new Set(state.candidates.map(c=>c.id));collector=JSON.parse(native.status());reloadStored();const queue=JSON.parse(native.queue());if(queue.length)commit('INGEST',queue,undefined,queue.map(c=>c.queueId));else render();if(process)native.processQueue?.();if(state.candidates.some(c=>c.autoRecorded&&!known.has(c.id)))toast('付款已自动记录，今日可用额度已更新；用途可以稍后补充');}catch(e){toast('处理采集队列失败，候选仍保留：'+e.message);}}
window.nativeEvent=(type,payload)=>guarded(()=>{if(ruleEditor?.event(type,payload))return;if(type==='resume')drain();else if(type==='ledger-updated')drain(false);else if(type==='ocr-start')toast('正在本地识别中文截图…');else if(type==='ocr'){const c=C.parsePayment(payload.text,{source:'ocr'});if(!payload.text.trim())throw new Error('图片中没有识别到文字，请换一张清晰截图');commit('INGEST',c,{auto:false});page='ledger';ledgerTab='pending';render();toast('截图已识别，请核对实际金额与交易状态');}else if(type==='csv')previewCSV(payload.text);else if(type==='backup')previewBackup(payload.text);else if(type==='error')toast(payload.message);else if(type==='saved')toast('文件已保存');});
action('nav',el=>{page=el.dataset.page;render();window.scrollTo(0,0);});action('close-sheet',()=>window.closeSheet());action('new',()=>txSheet());action('income',()=>txSheet({type:'income'}));action('transfer',()=>txSheet({type:'transfer'}));action('plan',planSheet);action('adjust',adjust);action('activity',activitySheet);action('detail',el=>details(el.dataset.id));action('edit-tx',el=>txSheet({tx:state.transactions.find(x=>x.id===el.dataset.id)}));action('void-tx',el=>{commit('VOID',el.dataset.id);window.closeSheet();toast('流水状态已更新，统计同步重算');});action('pending',()=>{page='ledger';ledgerTab='pending';render();});action('tab',el=>{ledgerTab=el.dataset.tab;render();});action('confirm',el=>reviewCandidate(state.candidates.find(x=>x.id===el.dataset.id)));
action('merge',el=>{sheet('确认是同一笔交易',`<p class="muted">只有确认这条候选与下方已记流水是同一次资金变动，才应关联。相同金额也可能是不同交易。</p>${entry(state.transactions.find(x=>x.id===el.dataset.tx))}${submit('关联，不新增收支')}`,()=>{commit('MERGE',{id:el.dataset.id,transactionId:el.dataset.tx});window.closeSheet();});});
action('dismiss',el=>{commit('DISMISS',el.dataset.id);toast('已忽略，不产生收支');});action('activity-spend',el=>txSheet({budgetId:el.dataset.budget}));action('cancel-activity',el=>{sheet('取消活动',`<p class="muted">释放未使用预留到待分配资金；已支付消费仍保留，退款到账后另记关联退款。</p>${submit('取消活动并释放剩余')}`,()=>{commit('CANCEL_ACTIVITY',el.dataset.id);window.closeSheet();});});
action('carry-activity',el=>sheet('保留到下个月',`<p class="muted">将这项活动尚未使用的预留带到目标月，不算收入，也不会再次分给日常预算。先创建目标月计划。</p>${field('目标月份','month','','month','required')}${submit('保留资金')}`,f=>{commit('CARRY_ACTIVITY',{id:el.dataset.id,toMonth:f.month});window.closeSheet();}));
action('account',el=>{const a=state.accounts.find(x=>x.id===el.dataset.id);sheet(a?'编辑账户':'添加账户',`<div class="form-grid">${field('账户名称','name',a?.name||'','text','required maxlength="40"')}${select('账户类型','type',[['wallet','日常 / 储值账户'],['savings','储蓄账户'],['credit','信用账户']],a?.type||'wallet')}${cashField('启用时的期初余额','opening',a?C.yuan(a.opening):'0','required')}${field('期初余额对应日期（当日开始）','openingDay',a?.openingDay&&a.openingDay!=='1970-01-01'?a.openingDay:today,'date','required')}<div class="form-note">期初余额不计作收入。信用欠款用负数；后续实际收支用流水登记，避免反复修改期初。月中启用时填写所选日期开始时可核对的资金；更早的导入流水保留统计，但不重复增减此期初资金。</div>${a?'<label class="field full checkbox-note"><span><input name="confirmOpening" type="checkbox" required> 我确认修改期初会改变所有历史推算余额。</span></label>':''}</div>${submit()}`,f=>{commit('ACCOUNT',{id:a?.id,name:f.name,type:f.type,opening:C.money(f.opening),openingDay:f.openingDay,confirmOpening:!!f.confirmOpening});window.closeSheet();});});
action('goal',()=>{const p=state.plans[month];if(!p)return planSheet();sheet('给未来，留一个目标',`${cashField('储蓄目标','amount',C.yuan(p.goalTarget??p.savings),'required')}${field('截止日期','deadline',p.goalDeadline||month+'-'+C.daysInMonth(month),'date','required')}<p class="muted">目标与预算预留分别保存。这里不调动预留资金；需要改预留时请使用预算调拨并确认。</p>${submit('保存目标')}`,f=>{commit('GOAL',{month,amount:C.money(f.amount),deadline:f.deadline});window.closeSheet();});});
action('plan-income',()=>sheet('修订计划生活费',`${cashField('计划金额','amount',C.yuan(state.plans[month].income),'required')}<p class="muted">只更改计划，已到账和已分配预算不变。</p>${submit()}`,f=>{commit('PLAN_INCOME',{month,amount:C.money(f.amount)});window.closeSheet();}));
action('suggest-plan',()=>{const form=$('#form'),f=Object.fromEntries(new FormData(form)),p=C.planProposal({month,income:C.money(f.income),savings:C.money(f.savings),emergency:C.money(f.emergency),fixed:C.money(f.fixed),foodFloor:C.money(f.foodFloor),transportFloor:C.money(f.transportFloor),startDay:Number(f.startDay)});p.budgets.forEach(b=>form.elements[b.id].value=C.yuan(b.allocated));form.dispatchEvent(new Event('input'));});
