action('deepseek-settings',()=>{const a=JSON.parse(native.deepSeekStatus());sheet('DeepSeek 识别兜底',`<p>使用你自己的 API Key，直接连接 DeepSeek 官方接口（deepseek-flash），按其 API 价格计费。密钥在本机加密保存，不写入账本、备份或源码。</p><p class="muted">开启后，本地失败时才发送所选付款截图或已授权付款窗口图像，可能包含商户、金额、时间及交易号。截图完成后，即使离开付款页也会继续处理这张图；关闭 DeepSeek 会取消未完成的云端结果。付款窗口中的明确付款会自动查重并预扣额度，用途可后补；手动选择的历史截图仍需核对后补记。信息不明或疑似重复不自动扣款。每次至多一次云端请求，间隔至少15秒，每日最多50次；断网和超时可继续手动记账。本地 OCR 使用的 ML Kit SDK 另有设备与性能诊断数据收集，关闭 DeepSeek 不等于禁止全部 SDK 联网。</p><label class="field"><span>DeepSeek API Key${a.configured?'（留空保留已保存密钥）':''}</span><input name="apiKey" type="password" autocomplete="off" spellcheck="false" maxlength="256" placeholder="仅在本机输入，不发到聊天中"></label><label class="checkbox-note"><input name="enabled" type="checkbox" ${a.enabled?'checked':''}><span>本地失败时使用 DeepSeek</span></label><label class="checkbox-note"><input name="consent" type="checkbox"><span>我了解并同意上述付款图片上传范围及 API 计费。</span></label>${submit('保存设置')}<button class="text-btn" type="button" data-action="deepseek-forget">关闭并清除密钥</button>`,f=>{const result=native.configureDeepSeek(!!f.enabled,f.apiKey||'',false,!!f.consent);const input=$('[name=apiKey]');if(input)input.value='';if(result!=='ok')throw new Error(result);window.closeSheet();render();toast(f.enabled?'DeepSeek 兜底已开启；明确付款自动查重记录':'已关闭云端识别');});});
action('deepseek-forget',()=>{const result=native.configureDeepSeek(false,'',true,false);if(result!=='ok')throw new Error(result);const input=$('[name=apiKey]');if(input)input.value='';window.closeSheet();render();toast('云端识别已关闭，密钥已清除');});
