action('alipay-page-permission',()=>{
 if(!native||!collector.pageOcrSupported){toast('需要 Android 14 及以上的 APK');return;}
 sheet('支付宝付款窗口 OCR',`<p>通过系统已授权的无障碍服务，读取当前已适配的支付宝付款结果或消费账单窗口图像，在本机最多识别三次，不操作支付宝、不持续录屏。</p><p class="muted">部分账单使用通用网页窗口。只有识别到完整付款结构、明确成功状态和实付金额才记录；输入控件、敏感文字、受保护窗口或不完整数据会停止处理，不保存整页图像或识别全文。其他支付宝页面仍可能未适配。</p><p class="muted">启用后，重新打开已支持的历史消费详情也可能按原日期生成候选；请核对已有记录。系统服务未连接时，需要在系统设置中开启余白付款识别。</p><label class="checkbox-note"><input name="consent" type="checkbox" required><span>我了解支付宝窗口读取范围，同意启用本地识别。</span></label>${submit('启用支付宝识别')}`,f=>{if(!f.consent)throw new Error('请确认读取范围');commit('SETTINGS',{pageCapture:true,pageOcr:true,alipayPageCapture:true,sources:[...new Set([...state.settings.sources,'com.eg.android.AlipayGphone'])]});window.closeSheet();toast('支付宝识别已启用，付款后请停留在成功页');if(!collector.accessibilityConnected)native.openAccessibilitySettings();});
});
action('page-ocr-disable',()=>{commit('SETTINGS',{pageOcr:false});toast('已关闭窗口 OCR 增强');});
action('payment-recognition',()=>{
 if(!native||!collector.pageOcrSupported){toast('微信窗口 OCR 需要 Android 14 及以上的 APK；可选择截图识别');return;}
 if(!state.settings.pageCapture||!state.settings.pageOcr||!state.settings.sources.includes('com.tencent.mm')){actions['page-ocr-permission']();return;}
 const ready=collector.accessibilityAuthorized&&collector.accessibilityConnected;
 const title=!collector.accessibilityAuthorized?'等待无障碍授权':!collector.accessibilityConnected?'无障碍服务未连接':'微信付款识别已开启';
 sheet(title,`<p>使用无障碍窗口 OCR，在本机识别微信扫码付款、商家支付成功页或转账详情。付款后请停留在成功页约 5 秒；也可打开已适配的付款方转账详情。</p><p class="muted">${ready?'无需每次重新授权。':'请在系统设置中启用余白页面识别；已授权但未连接时，可关闭后重新开启。'}${state.settings.autoRecordPayments===false?'成功付款自动记录目前已关闭，采集结果先待核对。':'明确付款先记录金额并预扣日常额度，用途稍后补充。'}旧交易按原发生日期归属，疑似重复不再次预扣。</p>${collector.pageOcrMessage?`<div class="notice">${esc(collector.pageOcrMessage)}</div>`:''}<div class="form-actions">${button(ready?'查看识别设置':'前往系统授权',ready?'recognition-settings':'page-permission',true)}${button('知道了','close-sheet')}</div>`);
});
action('recognition-settings',()=>{window.closeSheet();page='settings';render();});
action('page-ocr-permission',()=>{
 if(!native||!collector.pageOcrSupported){toast('需要 Android 14 及以上的新版 APK');return;}
 sheet('启用微信付款窗口 OCR',`<p>当微信付款结果或转账详情文字不可读时，通过已授权的无障碍服务请求该窗口的截图，在本机识别。每次打开仅作一次高清识别，不持续录屏，不操作微信。看到“已截取付款图，可离开页面”提示后即可返回聊天或切换应用，后台继续识别和查重。关闭识别会取消未完成任务。</p><p class="muted">仅限已适配的付款结果及转账详情窗口，不读取付款输入或密码页，不截取整个屏幕，不保存图像、聊天或识别全文。默认不上传；单独启用 DeepSeek 后，失败的付款图片可能发至云端。系统可能拒绝截图，届时显示原因并停止。金额、本人付款方向和状态明确才自动记录；已有凭证疑似重复时不再次预扣。</p><p class="muted">首次启用后，请在系统中关闭并重新开启余白页面识别，以更新截图能力授权。旧交易按原转账日期归属，不会伪装成今天消费。</p><label class="checkbox-note"><input name="consent" type="checkbox" required><span>我了解窗口图像读取范围，同意开启此增强并前往系统授权。</span></label>${submit('启用并前往授权')}`,f=>{if(!f.consent)throw new Error('请确认读取范围');commit('SETTINGS',{pageCapture:true,pageOcr:true,sources:[...new Set([...state.settings.sources,'com.tencent.mm'])]});window.closeSheet();native.openAccessibilitySettings();});
});
action('page-permission',()=>{
 if(!native)return;
 if(state.settings.pageCapture){native.openAccessibilitySettings();return;}
 sheet('启用微信页面识别',`<p>此功能使用 Android 无障碍访问读取系统提供的微信交易详情文字，用于个人记账，不是面向残障人士的无障碍工具。</p><p class="muted">仅在你启用微信来源和页面识别后工作。无关聊天、输入框、密码内容不入账；不保存页面全文；DeepSeek 图片上传需另行开启。部分微信版本或系统可能不提供页面文字；开启权限不保证所有页面可读。</p><p class="muted">成功付款自动记录开启时，明确支付会在后台保存金额并预扣日常额度，稍后再补用途。借款或还款可标为「非日常消费」释放预扣；识别不确定时仍待核对。</p><label class="checkbox-note"><input name="consent" type="checkbox" required><span>我了解读取范围，同意启用微信来源与页面识别，并前往系统手动授权。</span></label>${submit('启用并前往授权')}`,f=>{if(!f.consent)throw new Error('请先确认读取范围');commit('SETTINGS',{pageCapture:true,sources:[...new Set([...state.settings.sources,'com.tencent.mm'])]});window.closeSheet();native.openAccessibilitySettings();});
});

action('transfer-expense',el=>{const c=state.candidates.find(x=>x.id===el.dataset.id);if(c?.fundsStatus==='paid_out')txSheet({candidate:c,type:'expense'});});
action('payment-purpose',el=>{
 const c=state.candidates.find(x=>x.id===el.dataset.id);if(!c?.autoRecorded||c.status!=='pending')return;
 if(!c.suspectedCandidateId){txSheet({candidate:c,type:'expense'});return;}
 const prior=state.candidates.find(x=>x.id===c.suspectedCandidateId);
 sheet('先核对，是不是同一笔',`<p>这笔 ${amount(c.amount)} 与另一条已记录付款金额及付款凭证相似，目前没有重复预扣。</p><p class="muted">若来自同一笔支付的通知和页面，选择「同一笔付款」。如果确实付了两次，选择「确实是另一笔」，之后会分别计入消费。</p><div class="forecast-row"><span>已有付款</span><strong>${amount(prior?.amount||0)}</strong></div><p class="muted">${esc(prior?sourceName(prior.source,prior):'原记录')} · ${esc(prior?C.dayAt(prior.occurredAt,state.settings.timezone):'')}</p><div class="form-actions">${button('同一笔付款','same-payment',true,`data-id="${esc(c.id)}" data-with="${esc(c.suspectedCandidateId)}"`)}${button('确实是另一笔','distinct-payment',false,`data-id="${esc(c.id)}"`)}</div>`);
});
action('same-payment',el=>{commit('MERGE_PAYMENT',{id:el.dataset.id,withId:el.dataset.with});const merged=state.candidates.find(c=>c.id===el.dataset.id),target=state.candidates.find(c=>c.id===(merged?.duplicateOf||el.dataset.with));if(target?.status==='pending')txSheet({candidate:target,type:'expense'});else if(target?.transactionId)details(target.transactionId);else{window.closeSheet();toast('已关联同一笔付款，没有新增预扣');}});
action('distinct-payment',el=>{const c=state.candidates.find(x=>x.id===el.dataset.id);if(c?.status==='pending')txSheet({candidate:c,type:'expense',distinctPayment:true});});
action('release-payment-hold',el=>{commit('RELEASE_PAYMENT_HOLD',el.dataset.id);toast('已释放日常额度预扣；月底预测仍保留付款占款，补用途后校正');});
action('process-payments',()=>{native?.processQueue?.();drain(false);toast('已重试处理本地付款队列');});


function openRules(initialNew=false){
 sheet('自定义付款页适配','<div id="rule-editor-root"></div>',null,{kind:'rules'});
 ruleEditor=mountRuleEditor($('#rule-editor-root'),{
  native,getRules:()=>state.settings.customRules||[],toast,initialNew,supplement:reviewScreenshot,
  save:rule=>{const current=readStored().settings.customRules||[];commit('SETTINGS',{customRules:[...current.filter(r=>r.id!==rule.id),rule]});},
  remove:id=>{const current=readStored().settings.customRules||[];commit('SETTINGS',{customRules:current.filter(r=>r.id!==id)});}
 });
}
action('custom-rules',()=>openRules());action('screenshot-learn',()=>openRules(true));

function categoryManager(){
 sheet('我的消费分类',`<p class="muted">默认分类保留。自定义分类停用后不再供新账单选择，旧账单、退款和统计仍保留名称与关联。</p><div class="form-actions">${button('添加消费分类','category-new',true)}</div>${(state.categories||[]).map(c=>`<div class="setting-row"><div><h3>${esc(c.name)}</h3><p class="muted">${c.archived?'已停用':'使用中'}</p></div><div class="actions">${button('重命名','category-edit',false,`data-id="${esc(c.id)}"`)}${button(c.archived?'重新启用':'停用','category-toggle',false,`data-id="${esc(c.id)}"`)}</div></div>`).join('')||'<div class="empty">还没有自定义分类；也可以在记账时直接添加。</div>'}`);
}
function categorySheet(id){const c=state.categories?.find(c=>c.id===id);sheet(c?'重命名分类':'添加消费分类',`${field('分类名称','name',c?.name||'','text','required maxlength="24"')}<p class="muted">例如学习资料、医疗、宠物。新增分类不会新增一份预算；记账时仍需选择承担预算。</p>${submit('保存分类')}`,f=>{commit('CATEGORY',{id:c?.id||'cat-'+C.uid(),name:f.name});categoryManager();});}
action('categories',categoryManager);action('category-new',()=>categorySheet());action('category-edit',el=>categorySheet(el.dataset.id));
action('category-toggle',el=>{const c=state.categories.find(c=>c.id===el.dataset.id);commit('CATEGORY',{...c,archived:!c.archived});categoryManager();});

function reviewScreenshot(preview,metadata){
 const candidate=screenshotPayment(preview,metadata);commit('INGEST',candidate,{auto:false});
 const saved=state.candidates.find(c=>c.fingerprint===candidate.fingerprint);
 if(saved?.transactionId){details(saved.transactionId);toast('这张付款凭证已有账单，没有再次扣款');return;}
 if(saved?.status!=='pending'){window.closeSheet();toast('这张付款凭证已处理，没有再次入账');return;}
 reviewCandidate(saved);
}
function reviewCandidate(c,distinct=false){
 if(!c||c.status!=='pending')return;
 if(!distinct&&(c.suspectedCandidateId||c.suspectedId)){
  const candidate=c.suspectedCandidateId?state.candidates.find(x=>x.id===c.suspectedCandidateId):null;
  const prior=candidate||state.transactions.find(x=>x.id===c.suspectedId);
  sheet('先核对，是不是同一笔',`<p>这张截图可能对应已有的 ${amount(prior?.amount||0)} 付款。请确认，避免重复记账。</p><p class="muted">${esc(prior?.merchant||'已有付款')}</p><div class="form-actions">${c.suspectedCandidateId?button('同一笔付款','same-payment',true,`data-id="${esc(c.id)}" data-with="${esc(c.suspectedCandidateId)}"`):button('关联已有账单','link-screenshot',true,`data-id="${esc(c.id)}" data-tx="${esc(c.suspectedId)}"`)}${button('确实是另一笔','distinct-payment',false,`data-id="${esc(c.id)}"`)}</div>`);return;
 }
 txSheet({candidate:c,type:['expense','income','refund','transfer','complex'].includes(c.type)?c.type:'expense',distinctPayment:distinct});
}
action('link-screenshot',el=>{commit('MERGE',{id:el.dataset.id,transactionId:el.dataset.tx});details(el.dataset.tx);});
